before:
Complete local Kotlin/JVM example; the app itself does not execute it:
```kotlin
object Counter { var next = 1 }
class Ticket(val id: Int) {
    companion object {
        fun create(): Ticket {
            val ticket = Ticket(Counter.next)
            Counter.next += 1
            return ticket
        }
    }
}
fun main() {
    Ticket.create()
    println(Ticket.create().id)
}
```

